# A supply may take a cashier's drawer or wallet below zero (the balance then shows negative). Every other outflow
# still needs the money: an entry taking value out of a company asset account is refused when the account ends below
# zero, unless that entry belongs to a supply. Entries putting value in are always accepted (they repair a negative).
SQL = r"""
CREATE OR REPLACE FUNCTION core_check_asset_nonnegative() RETURNS trigger AS $$
DECLARE k text; s numeric; t text;
BEGIN
  IF NEW.amount >= 0 THEN
    RETURN NULL;
  END IF;
  SELECT kind INTO k FROM core_account WHERE id = NEW.account_id;
  IF k IN ('CASH_DRAWER', 'UVE', 'ER', 'MTN', 'BANK') THEN
    SELECT type INTO t FROM core_transaction WHERE id = NEW.transaction_id;
    IF t = 'SUPPLY' THEN
      RETURN NULL;
    END IF;
    SELECT COALESCE(SUM(amount), 0) INTO s FROM core_entry WHERE account_id = NEW.account_id;
    IF s < 0 THEN
      RAISE EXCEPTION 'Company asset account % would become negative (%)', NEW.account_id, s
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NULL;
END $$ LANGUAGE plpgsql;
"""

